  expectType<EsiError>(err);
}

if (isServerError(err)) {
  expectType<EsiError>(err);
}

if (isTimeout(err)) {
  expectType<TimeoutError>(err);
  expectType<number>(err.timeoutMs);
}

if (isValidationError(err)) {
  expectType<EsiValidationError>(err);
  expectType<unknown>(err.validationError);
